{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-v8bXuN/src/policies.js","content":"/**
 * The two policy kinds a limiter file can declare. Both keep one
 * independent state per key, created lazily the first time that key
 * reaches the policy.
 */

/**
 * A token bucket. Tokens are tracked as an integer count of "per"-ths of a
 * token (tokensNum = tokens * per), so refilling by `refill` tokens every
 * `per` ticks never needs anything but exact integer arithmetic.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityNum = capacity * per
    this.byKey = new Map()
  }

  advance(tick, key) {
    let state = this.byKey.get(key)
    if (!state) {
      this.byKey.set(key, { tokensNum: this.capacityNum, lastTick: tick })
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.tokensNum += this.refill * elapsed
      if (state.tokensNum > this.capacityNum) state.tokensNum = this.capacityNum
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.byKey.get(key).tokensNum >= this.per
  }

  record(key) {
    this.byKey.get(key).tokensNum -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for
 * each key, oldest first, so advancing only ever needs to drop from the
 * front.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.byKey = new Map()
  }

  advance(tick, key) {
    let ticks = this.byKey.get(key)
    if (!ticks) {
      ticks = []
      this.byKey.set(key, ticks)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= threshold) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allow(key) {
    return BigInt(this.byKey.get(key).length) < this.limit
  }

  record(key, tick) {
    this.byKey.get(key).push(tick)
  }
}
"}

