{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-v8bXuN/src/parser.js","content":"/**
 * Parses a limiter file and, in the same pass, replays every event through
 * the declared policies. Splitting parsing from simulation would need a
 * second pass over the same events for no benefit, since a limiter file's
 * declarations are always complete before its first event.
 */
import { CliError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const IDENT = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function parseUint(token, field, min) {
  if (!UINT.test(token) || BigInt(token) < BigInt(min)) {
    throw new CliError(`${field} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

function checkIdent(token, kind, message) {
  if (!IDENT.test(token)) throw new CliError(`${message} ${token}`)
  return token
}

/**
 * Runs a limiter file read as a single string and returns
 * `{ records, totals, order }`: `records` is one `{ tick, key, allowed,
 * denyPolicy }` per event in log order, `totals` maps each key to its
 * `{ allowed, denied }` counts, and `order` lists the keys in the order
 * they first appeared. Throws `CliError` with a `line N: ...` message on
 * the first malformed line.
 */
export function run(input) {
  const rawLines = input.length === 0 ? [] : input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()

  const records = []
  const totals = new Map()
  const order = []

  let eventSeen = false
  let lastTick = null

  function findRoute(key) {
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) best = route
      }
    }
    return best
  }

  rawLines.forEach((rawLine, index) => {
    const lineNumber = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    try {
      switch (directive) {
        case 'bucket': {
          if (eventSeen) throw new CliError('declarations must come before the first event')
          if (tokens.length !== 5) throw new CliError('expected bucket <name> <capacity> <refill> <per>')
          const name = checkIdent(tokens[1], 'name', 'invalid policy name')
          if (policies.has(name)) throw new CliError(`policy ${name} is declared twice`)
          const capacity = parseUint(tokens[2], 'capacity', 1)
          const refill = parseUint(tokens[3], 'refill', 0)
          const per = parseUint(tokens[4], 'per', 1)
          policies.set(name, new TokenBucket(capacity, refill, per))
          break
        }
        case 'window': {
          if (eventSeen) throw new CliError('declarations must come before the first event')
          if (tokens.length !== 4) throw new CliError('expected window <name> <limit> <span>')
          const name = checkIdent(tokens[1], 'name', 'invalid policy name')
          if (policies.has(name)) throw new CliError(`policy ${name} is declared twice`)
          const limit = parseUint(tokens[2], 'limit', 0)
          const span = parseUint(tokens[3], 'span', 1)
          policies.set(name, new SlidingWindow(limit, span))
          break
        }
        case 'route': {
          if (eventSeen) throw new CliError('declarations must come before the first event')
          if (tokens.length < 3) throw new CliError('expected route <prefix> <policy>...')
          const prefix = checkIdent(tokens[1], 'prefix', 'invalid route prefix')
          if (routePrefixes.has(prefix)) throw new CliError(`prefix ${prefix} is routed twice`)
          const routed = []
          for (const name of tokens.slice(2)) {
            const policy = policies.get(name)
            if (!policy) throw new CliError(`unknown policy ${name}`)
            routed.push({ name, policy })
          }
          routePrefixes.add(prefix)
          routes.push({ prefix, policies: routed })
          break
        }
        case 'event': {
          if (tokens.length !== 3) throw new CliError('expected event <tick> <key>')
          const tick = parseUint(tokens[1], 'tick', 0)
          const key = checkIdent(tokens[2], 'key', 'invalid key')
          if (lastTick !== null && tick < lastTick) {
            throw new CliError(`tick ${tick} is before tick ${lastTick}`)
          }
          lastTick = tick
          eventSeen = true

          const route = findRoute(key)
          let allowed = true
          let denyPolicy = null
          if (route) {
            for (const { policy } of route.policies) policy.advance(tick, key)
            for (const { name, policy } of route.policies) {
              if (!policy.allow(key)) {
                allowed = false
                denyPolicy = name
                break
              }
            }
            if (allowed) {
              for (const { policy } of route.policies) policy.record(key, tick)
            }
          }

          if (!totals.has(key)) {
            totals.set(key, { allowed: 0, denied: 0 })
            order.push(key)
          }
          const count = totals.get(key)
          if (allowed) count.allowed++
          else count.denied++

          records.push({ tick, key, allowed, denyPolicy })
          break
        }
        default:
          throw new CliError(`unknown directive ${directive}`)
      }
    } catch (err) {
      if (err instanceof CliError) throw new CliError(`line ${lineNumber}: ${err.message}`)
      throw err
    }
  })

  return { records, totals, order }
}
"}

